-- Future-ready costing: missing actual data is NR; TEST-only E2E provisions must be explicitly tagged.
create or replace function public.rr_costing_nr_provision_policy_v405() returns jsonb language sql immutable as $function$
select jsonb_build_object('version','V405_NR_PROVISION_POLICY','missing_state','NR','missing_label','NOT_RECORDED','test_provision_source_type','TEST71_E2E_PROVISION','test_provision_reference_prefix','TEST71-E2E-PROVISION-','rules',jsonb_build_array('MISSING REAL COST DATA DOES NOT INVENT ACTUAL VALUE','TEST MODE MAY USE CLEARLY TAGGED PROVISION FOR E2E','PROVISION NEVER PRESENTED AS ACTUAL','REAL DATA AUTOMATICALLY REPLACES NR/PROVISION THROUGH CANONICAL SOURCE'));
$function$;
create or replace function public.rr_costing_overhead_allocation_v405(p_canonical_lot_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare o jsonb:=public.rr_costing_overhead_allocation_v648(p_canonical_lot_id,p_data_mode);n int:=0;begin select count(*) into n from public.rr_cost_expense_pool_v850 e join public.rr_upm_lot_registry l on l.canonical_lot_id=p_canonical_lot_id where upper(e.data_mode)=upper(p_data_mode) and e.is_active and e.business_stream in('MANUFACTURING','ALL','FACTORY') and l.created_at::date between e.period_start and e.period_end;return o||jsonb_build_object('expense_state',case when n=0 then 'NR' else 'RECORDED' end,'expense_label',case when n=0 then 'NOT_RECORDED' else 'RECORDED' end,'provision_allowed',upper(p_data_mode)='TEST','provision_tag','TEST71_E2E_PROVISION','policy',public.rr_costing_nr_provision_policy_v405());end $function$;